        self._keys = {}  # Key -> LRU value (default: -1)
        self._values = []

    def get(self, key: int) -> int:
        if key in self._keys:
            return self._keys[key]

        if len(self._values) >= self.capacity:
            # LRU oldest is at the end, so remove it first
